"""S3 implementation of EventArchive: one JSON object per run, partitioned by UTC date.

Key: runs/YYYY/MM/DD/<run_id>.json. Date prefixes let analytics (M6) list one day at a time.
"""

import json
import re
from datetime import UTC
from typing import TYPE_CHECKING

from backend.domain.events import run_to_event
from backend.domain.models import Run

if TYPE_CHECKING:
    from mypy_boto3_s3.client import S3Client

# run_id is generated by the server (UUID4), but it still goes into an object key:
# allow only characters that cannot change the path.
SAFE_ID = re.compile(r"[A-Za-z0-9-]{1,64}")


def event_key(run: Run) -> str:
    if not SAFE_ID.fullmatch(run.run_id):
        raise ValueError("run_id: unsafe characters for an S3 key")
    day = run.received_at.astimezone(UTC)
    return f"runs/{day:%Y/%m/%d}/{run.run_id}.json"


class S3EventArchive:
    def __init__(self, s3: "S3Client", bucket: str) -> None:
        self._s3 = s3
        self._bucket = bucket

    def store(self, run: Run) -> None:
        self._s3.put_object(
            Bucket=self._bucket,
            Key=event_key(run),
            Body=json.dumps(run_to_event(run), separators=(",", ":")).encode("utf-8"),
            ContentType="application/json",
        )
